import torch, sys
sys.path.insert(0, "/app/miles")
from miles.utils.types import Sample
from transformers import AutoTokenizer

def spans(lm):
    out=[]; i=0
    while i < len(lm):
        if lm[i]:
            j=i
            while j < len(lm) and lm[j]:
                j+=1
            out.append((i,j)); i=j
        else:
            i+=1
    return out

def render(tok, messages, tools, gen, extra):
    kw = {"tokenize": False, "add_generation_prompt": gen}
    kw.update(extra or {})
    if tools:
        kw["tools"] = tools
    try:
        return tok.apply_chat_template(messages, **kw)
    except TypeError:
        kw.pop("tools", None)
        return tok.apply_chat_template(messages, **kw)

teachers = {
    "qwen3": ("/models/Qwen3-8B", {"enable_thinking": False}),
    "qwen3think": ("/models/Qwen3-8B", {"enable_thinking": True}),
    "falcon": ("/models/Falcon-H1R-7B", {}),
}
toks = {k: AutoTokenizer.from_pretrained(p, trust_remote_code=True) for k,(p,_) in teachers.items()}

kinds = {
    "mswea": "/app/data/rollouts/mswea/rollout_0.pt",
    "terminus_think": "/app/data/rollouts/terminus_think/rollout_0.pt",
    "sql": "/app/data/rollouts/sql/rollout_0.pt",
}

for kind, path in kinds.items():
    d = torch.load(path, map_location="cpu", weights_only=False)
    samples = [Sample.from_dict(r) for r in d["samples"]]
    print("\n####", kind, "samples", len(samples))
    for tname, (tpath, extra) in teachers.items():
        tok = toks[tname]
        stats = dict(turns=0, prompt_ok=0, hist_ok=0, neither=0, prompt_and_hist=0)
        neither_ex = None
        for s in samples:
            msgs = s.metadata["messages"]
            tools = s.metadata.get("tools")
            asst_idx = [i for i,m in enumerate(msgs) if m.get("role")=="assistant"]
            sp = spans(s.loss_mask or [])
            n = min(len(asst_idx), len(sp))
            for k in range(n):
                ai = asst_idx[k]
                stats["turns"] += 1
                full = render(tok, msgs[:ai+1], tools, False, extra)
                prompt = render(tok, msgs[:ai], tools, True, extra)
                hist = render(tok, msgs[:ai], tools, False, extra)
                pok = full.startswith(prompt)
                hok = full.startswith(hist)
                if pok: stats["prompt_ok"] += 1
                if hok: stats["hist_ok"] += 1
                if pok and hok: stats["prompt_and_hist"] += 1
                if not pok and not hok:
                    stats["neither"] += 1
                    if neither_ex is None:
                        neither_ex = (s.index, k, ai, len(full), len(prompt), len(hist), full[:80], prompt[:80], hist[:80])
        print(tname, stats)
        if neither_ex:
            print("  neither ex", neither_ex)
