from miles.utils.types import Sample
from transformers import AutoTokenizer

def bytes_to_unicode():
    bs = list(range(ord("!"), ord("~")+1)) + list(range(ord("¡"), ord("¬")+1)) + list(range(ord("®"), ord("ÿ")+1))
    cs = bs[:]
    n = 0
    for b in range(256):
        if b not in bs:
            bs.append(b)
            cs.append(256+n)
            n += 1
    return dict(zip(bs, [chr(c) for c in cs]))

BYTE_DECODER = {v: k for k, v in bytes_to_unicode().items()}

def encode(tok, text):
    if getattr(tok, "is_fast", False):
        return list(tok(text, add_special_tokens=False)["input_ids"])
    return list(tok.encode(text, add_special_tokens=False))

def pieces(tok, ids):
    specials = set(getattr(tok, "all_special_tokens", []) or [])
    # also ids
    special_ids = set(getattr(tok, "all_special_ids", []) or [])
    tokens = tok.convert_ids_to_tokens(ids)
    parts = []
    for i, (tid, tokstr) in enumerate(zip(ids, tokens)):
        if tokstr is None:
            parts.append(("lit", i, ""))
            continue
        if tid in special_ids or tokstr in specials or (tokstr.startswith("<|") and tokstr.endswith("|>")):
            parts.append(("lit", i, tokstr))
            continue
        try:
            raw = bytes(BYTE_DECODER[c] for c in tokstr)
        except KeyError:
            parts.append(("lit", i, tokstr))
            continue
        parts.append(("bytes", i, raw))
    out = [""] * len(ids)
    i = 0
    while i < len(parts):
        kind, idx, data = parts[i]
        if kind == "lit":
            out[idx] = data
            i += 1
            continue
        group = []
        while i < len(parts) and parts[i][0] == "bytes":
            group.append(parts[i])
            i += 1
        all_bytes = b"".join(raw for _,_,raw in group)
        owners = []
        for _, idx, raw in group:
            owners.extend([idx]*len(raw))
        j = 0
        n = len(all_bytes)
        while j < n:
            b0 = all_bytes[j]
            if b0 < 0x80:
                clen = 1
