"""Teacher scoring when the teacher's tokenizer is not the student's.

The teacher judges each turn as it would see that turn: the episode messages up through the
turn, rendered with the teacher's chat template (YAML chat-template kwargs and the episode's
tools). The server scores those token ids. Student positions are never re-tokenized; the
response tokens and loss_mask are the student's own writing.

Alignment is by text, not by token id. A 1:1 decoded match copies that teacher log-prob.
A longer match keeps the sum of the teacher's token log-probs and spreads it over the
student tokens in the match by character length, so every covered writing token gets signal
and the span's reverse KL stays the teacher's. Positions the teacher cannot judge — observations,
format the template does not share, dropped thinking, byte fragments — keep the rollout
log-prob, which is no distillation signal. loss_mask is left alone so the verdict advantage
still trains.
"""

import asyncio
import logging
import math
from difflib import SequenceMatcher

import aiohttp
import torch

from miles.rollout.on_policy_distillation import _teacher_url_for_sample
from miles.utils.types import Sample

logger = logging.getLogger(__name__)

# GPT-2 / ByteLevel BPE byte↔unicode map. transformers no longer exports this from a stable path.
def _bytes_to_unicode():
    bs = (
        list(range(ord("!"), ord("~") + 1))
        + list(range(ord("¡"), ord("¬") + 1))
        + list(range(ord("®"), ord("ÿ") + 1))
    )
    cs = bs[:]
    n = 0
    for b in range(256):
        if b not in bs:
            bs.append(b)
            cs.append(256 + n)
            n += 1
    return dict(zip(bs, [chr(c) for c in cs]))


_BYTE_DECODER = {v: k for k, v in _bytes_to_unicode().items()}
_SPECIAL_IDS: dict[int, set[int]] = {}
_SPECIAL_STRS: dict[int, set[str]] = {}


def _get_teacher_semaphore(args):
    loop = asyncio.get_running_loop()
    loop_key = id(loop)
    semaphores_by_loop = getattr(args, "_opd_teacher_semaphores", None)
    if semaphores_by_loop is None:
        semaphores_by_loop = {}
        args._opd_teacher_semaphores = semaphores_by_loop

    concurrency = int(getattr(args, "opd_teacher_concurrency", 0) or 0)
    if concurrency <= 0:
        return None

    semaphore = semaphores_by_loop.get(loop_key)
    if semaphore is None:
        semaphore = asyncio.Semaphore(concurrency)
        semaphores_by_loop[loop_key] = semaphore
    return semaphore


def _get_teacher_session(args):
    """Reuse one client session per event loop. Hundreds of per-turn scores otherwise pay a handshake each."""
    loop = asyncio.get_running_loop()
    loop_key = id(loop)
    sessions = getattr(args, "_opd_teacher_sessions", None)
    if sessions is None:
        sessions = {}
        args._opd_teacher_sessions = sessions
    session = sessions.get(loop_key)
    if session is None or session.closed:
        timeout = aiohttp.ClientTimeout(total=float(getattr(args, "opd_teacher_timeout", 300.0)))
        session = aiohttp.ClientSession(timeout=timeout)
        sessions[loop_key] = session
    return session


def _teacher_payload_summary(payload):
    if "input_ids" in payload:
        ids = payload["input_ids"]
        if ids and isinstance(ids[0], list):
            return f"batch={len(ids)} input_tokens={max(len(x) for x in ids)}"
        return f"input_tokens={len(ids)}"
    if "text" in payload:
        return f"text_chars={len(payload['text'])}"
    return "payload_size=unknown"


async def _post_teacher_once(session, teacher_url, payload):
    async with session.post(teacher_url, json=payload) as resp:
        if resp.status >= 400:
            body = (await resp.text())[:500]
            raise aiohttp.ClientResponseError(
                request_info=resp.request_info,
                history=resp.history,
                status=resp.status,
                message=f"{resp.reason}; body={body}",
                headers=resp.headers,
            )
        return await resp.json()


async def _post_teacher_json(args, teacher_url, payload, sample, warning_prefix):
    retries = max(0, int(getattr(args, "opd_teacher_retries", 2)))
    semaphore = _get_teacher_semaphore(args)
    last_exc = None

    for attempt in range(retries + 1):
        try:
            session = _get_teacher_session(args)
            if semaphore is None:
                return await _post_teacher_once(session, teacher_url, payload)
            async with semaphore:
                return await _post_teacher_once(session, teacher_url, payload)
        except (TimeoutError, asyncio.TimeoutError, aiohttp.ClientError) as exc:
            last_exc = exc
            if attempt < retries:
                await asyncio.sleep(min(0.2 * (2**attempt), 2.0))
                continue

    logger.warning(
        "%s failed after %s attempt(s); leaving those positions without teacher signal "
        "for sample index=%s (%s): %s: %s",
        warning_prefix,
        retries + 1,
        getattr(sample, "index", None),
        _teacher_payload_summary(payload),
        type(last_exc).__name__,
        last_exc,
    )
    return {"_opd_teacher_fallback": True, "_opd_teacher_fallback_reason": type(last_exc).__name__}


def _use_student_log_probs_for_teacher(sample: Sample, reason: str) -> None:
    resp_len = sample.response_length
    sample.teacher_log_probs = torch.tensor(_rollout_log_probs(sample), dtype=torch.float32)
    if sample.teacher_log_probs.numel() != resp_len:
        sample.teacher_log_probs = torch.zeros(resp_len, dtype=torch.float32)
    if sample.metadata is None:
        sample.metadata = {}
    sample.metadata["opd_teacher_fallback"] = True
    sample.metadata["opd_teacher_fallback_reason"] = reason


def _load_tokenizers(args):
    if hasattr(args, "_cross_vocab_student_tok") and hasattr(args, "_cross_vocab_teacher_tok"):
        return
    teacher_path = getattr(args, "teacher_tokenizer_path", None)
    if not teacher_path:
        raise ValueError("teacher_tokenizer_path is required to score a teacher with its own tokenizer.")
    from transformers import AutoTokenizer

    args._cross_vocab_student_tok = AutoTokenizer.from_pretrained(args.hf_checkpoint, trust_remote_code=True)
    args._cross_vocab_teacher_tok = AutoTokenizer.from_pretrained(teacher_path, trust_remote_code=True)


def teacher_uses_student_tokenizer(args) -> bool:
    """True when the teacher can score the student's token ids directly.

    No teacher_tokenizer_path keeps today's path (the run did not name a separate tokenizer).
    A named teacher uses that path only when its vocab is not the student's: Qwen3.5-9B names a
    tokenizer and still shares the student's vocab, so it must keep the token-id score.
    """
    path = getattr(args, "teacher_tokenizer_path", None)
    if not path:
        return True
    cached = getattr(args, "_opd_teacher_same_tokenizer", None)
    if cached is not None:
        return cached
    _load_tokenizers(args)
    same = args._cross_vocab_student_tok.get_vocab() == args._cross_vocab_teacher_tok.get_vocab()
    args._opd_teacher_same_tokenizer = same
    return same


def _template_kwargs(args) -> dict:
    extra = dict(getattr(args, "opd_teacher_chat_template_kwargs", None) or {})
    extra.pop("tokenize", None)
    extra.pop("add_generation_prompt", None)
    extra.pop("tools", None)
    return extra


def _messages(args, sample: Sample):
    metadata = sample.metadata or {}
    key = getattr(args, "opd_prompt_messages_key", None) or "messages"
    messages = metadata.get(key)
    if messages is None and isinstance(sample.prompt, list):
        messages = sample.prompt
    if not isinstance(messages, list):
        return None
    return messages


def _render(tokenizer, messages, tools, add_generation_prompt, template_kwargs) -> str:
    kwargs = {"tokenize": False, "add_generation_prompt": add_generation_prompt}
    kwargs.update(template_kwargs)
    if tools:
        kwargs["tools"] = tools
    try:
        text = tokenizer.apply_chat_template(messages, **kwargs)
    except TypeError:
        kwargs.pop("tools", None)
        text = tokenizer.apply_chat_template(messages, **kwargs)
    if not isinstance(text, str):
        raise TypeError(f"teacher chat template returned {type(text).__name__}, expected str")
    return text


def _encode(tokenizer, text: str) -> list[int]:
    # Match the SGLang / fake-teacher fast path: tokenizer(text) without added BOS.
    if getattr(tokenizer, "is_fast", False):
        return [int(i) for i in tokenizer(text, add_special_tokens=False)["input_ids"]]
    return [int(i) for i in tokenizer.encode(text, add_special_tokens=False)]


def _special_ids(tokenizer) -> set[int]:
    key = id(tokenizer)
    cached = _SPECIAL_IDS.get(key)
    if cached is None:
        cached = set(getattr(tokenizer, "all_special_ids", []) or [])
        _SPECIAL_IDS[key] = cached
    return cached


def _special_strs(tokenizer) -> set[str]:
    key = id(tokenizer)
    cached = _SPECIAL_STRS.get(key)
    if cached is None:
        cached = set(getattr(tokenizer, "all_special_tokens", []) or [])
        _SPECIAL_STRS[key] = cached
    return cached


def token_pieces(tokenizer, token_ids: list[int]) -> list[str]:
    """String each token contributes inside tokenizer.decode(token_ids).

    Per-token decode is not that string: byte-fallback and split UTF-8 put the character on
    the token that finishes it, and earlier tokens of the same character contribute nothing.
    Special tokens are flushed so they stay whole. Empty pieces are byte fragments; they
    cannot carry teacher signal.
    """
    if not token_ids:
        return []
    special_ids = _special_ids(tokenizer)
    special_strs = _special_strs(tokenizer)
    tokens = tokenizer.convert_ids_to_tokens(token_ids)
    parts: list[tuple[str, int, object]] = []
    for i, (tid, tok) in enumerate(zip(token_ids, tokens, strict=True)):
        if tok is None or tid in special_ids or tok in special_strs or (tok.startswith("<|") and tok.endswith("|>")):
            parts.append(("lit", i, tok or ""))
            continue
        try:
            raw = bytes(_BYTE_DECODER[c] for c in tok)
        except KeyError:
            parts.append(("lit", i, tok))
            continue
        parts.append(("bytes", i, raw))

    pieces = [""] * len(token_ids)
    i = 0
    while i < len(parts):
        kind, idx, data = parts[i]
        if kind == "lit":
            pieces[idx] = data
            i += 1
            continue
        group = []
        while i < len(parts) and parts[i][0] == "bytes":
            group.append(parts[i])
            i += 1
        all_bytes = b"".join(raw for _, _, raw in group)
        owners = []
        for _, gidx, raw in group:
            owners.extend([gidx] * len(raw))
        j = 0
        n = len(all_bytes)
        while j < n:
            b0 = all_bytes[j]
            if b0 < 0x80:
                clen = 1
            elif 0xC0 <= b0 <= 0xDF:
                clen = 2
            elif 0xE0 <= b0 <= 0xEF:
                clen = 3
            elif 0xF0 <= b0 <= 0xF7:
                clen = 4
            else:
                clen = 1
            if j + clen > n:
                pieces[owners[-1]] += all_bytes[j:].decode("utf-8", errors="replace")
                break
            chunk = all_bytes[j : j + clen]
            try:
                ch = chunk.decode("utf-8")
            except UnicodeDecodeError:
                ch = "\ufffd"
                clen = 1
            pieces[owners[j + clen - 1]] += ch
            j += clen
    return pieces


def _char_spans(pieces: list[str]) -> list[tuple[int, int]]:
    spans = []
    pos = 0
    for piece in pieces:
        spans.append((pos, pos + len(piece)))
        pos += len(piece)
    return spans


def _fully_inside(pieces, spans, lo, hi) -> list[int]:
    return [i for i, (start, end) in enumerate(spans) if pieces[i] and start >= lo and end <= hi]


def _distribute_logprob(total: float, chars: list[int]) -> list[float]:
    """Spread ``total`` over tokens in proportion to character length. The float32 sum equals float32(total)."""
    weights = torch.tensor(chars, dtype=torch.float32)
    total32 = torch.tensor(total, dtype=torch.float32)
    parts = total32 * (weights / weights.sum())
    if parts.numel() > 1:
        parts[-1] = total32 - parts[:-1].sum()
    return [float(x) for x in parts.tolist()]


def _assign_equal_chunks(aligned, s_idxs, t_idxs, student_pieces, teacher_pieces, teacher_lps) -> int:
    """Greedy minimal chunks whose concatenated pieces are equal. 1:1 copies the teacher log-prob."""
    si = ti = 0
    ns, nt = len(s_idxs), len(t_idxs)
    assigned = 0
    while si < ns and ti < nt:
        s_start, t_start = si, ti
        s_len = len(student_pieces[s_idxs[si]])
        t_len = len(teacher_pieces[t_idxs[ti]])
        si += 1
        ti += 1
        while s_len != t_len:
            if s_len < t_len:
                if si >= ns:
                    return assigned
                s_len += len(student_pieces[s_idxs[si]])
                si += 1
            else:
                if ti >= nt:
                    return assigned
                t_len += len(teacher_pieces[t_idxs[ti]])
                ti += 1
        chunk_s = s_idxs[s_start:si]
        chunk_t = t_idxs[t_start:ti]
        lps = []
        usable = True
        for j in chunk_t:
            lp = teacher_lps[j]
            if lp is None:
                usable = False
                break
            try:
                lp_f = float(lp)
            except (TypeError, ValueError):
                usable = False
                break
            if not math.isfinite(lp_f):
                usable = False
                break
            lps.append(lp_f)
        if not usable:
            continue
        if len(chunk_s) == 1 and len(chunk_t) == 1:
            aligned[chunk_s[0]] = float(torch.tensor(lps[0], dtype=torch.float32))
            assigned += 1
            continue
        chars = [len(student_pieces[j]) for j in chunk_s]
        if sum(chars) <= 0:
            continue
        for j, part in zip(chunk_s, _distribute_logprob(sum(lps), chars), strict=True):
            aligned[j] = part
            assigned += 1
    return assigned


def align_logprobs(student_pieces, teacher_pieces, teacher_lps, baseline) -> tuple[list[float], int]:
    """Copy teacher signal onto student pieces that spell the same text. Unmatched positions stay at baseline."""
    if len(baseline) != len(student_pieces):
        raise ValueError(
            f"baseline length {len(baseline)} != student pieces {len(student_pieces)}"
        )
    if len(teacher_pieces) != len(teacher_lps):
        raise ValueError(
            f"teacher pieces {len(teacher_pieces)} != teacher logprobs {len(teacher_lps)}"
        )
    aligned = list(baseline)
    student_text = "".join(student_pieces)
    teacher_text = "".join(teacher_pieces)
    if not student_text or not teacher_text:
        return aligned, 0

    s_spans = _char_spans(student_pieces)
    t_spans = _char_spans(teacher_pieces)
    assigned = 0
    matcher = SequenceMatcher(None, student_text, teacher_text, autojunk=False)
    for block in matcher.get_matching_blocks():
        if block.size <= 0:
            continue
        s_lo, s_hi = block.a, block.a + block.size
        t_lo, t_hi = block.b, block.b + block.size
        s_idxs = _fully_inside(student_pieces, s_spans, s_lo, s_hi)
        t_idxs = _fully_inside(teacher_pieces, t_spans, t_lo, t_hi)
        stable = False
        for _ in range(8):
            if not s_idxs or not t_idxs:
                break
            rel_lo = max(s_spans[s_idxs[0]][0] - s_lo, t_spans[t_idxs[0]][0] - t_lo)
            rel_hi = min(s_spans[s_idxs[-1]][1] - s_lo, t_spans[t_idxs[-1]][1] - t_lo)
            if rel_hi <= rel_lo:
                s_idxs, t_idxs = [], []
                break
            new_s = _fully_inside(student_pieces, s_spans, s_lo + rel_lo, s_lo + rel_hi)
            new_t = _fully_inside(teacher_pieces, t_spans, t_lo + rel_lo, t_lo + rel_hi)
            if new_s == s_idxs and new_t == t_idxs:
                stable = True
                break
            s_idxs, t_idxs = new_s, new_t
        if not stable or not s_idxs or not t_idxs:
            continue
        if "".join(student_pieces[i] for i in s_idxs) != "".join(teacher_pieces[i] for i in t_idxs):
            continue
        assigned += _assign_equal_chunks(
            aligned, s_idxs, t_idxs, student_pieces, teacher_pieces, teacher_lps
        )
    return aligned, assigned


def _mask_spans(loss_mask) -> list[tuple[int, int]]:
    spans = []
    i = 0
    n = len(loss_mask)
    while i < n:
        if loss_mask[i]:
            j = i + 1
            while j < n and loss_mask[j]:
                j += 1
            spans.append((i, j))
            i = j
        else:
            i += 1
    return spans


def _rollout_log_probs(sample: Sample) -> list[float]:
    resp_len = sample.response_length
    rollout = sample.rollout_log_probs
    if rollout is None:
        return [0.0] * resp_len
    if isinstance(rollout, torch.Tensor):
        vals = rollout.detach().to(dtype=torch.float32).flatten().tolist()
    else:
        vals = [float(x) for x in rollout]
    if len(vals) >= resp_len:
        return vals[-resp_len:]
    return [0.0] * (resp_len - len(vals)) + vals


def _completion_start(pieces: list[str], boundary: int) -> int:
    """First token whose text starts at or after ``boundary``. A token that straddles the boundary is excluded."""
    pos = 0
    for i, piece in enumerate(pieces):
        if pos >= boundary:
            return i
        pos += len(piece)
    return len(pieces)


def _prefix_owners(seqs: list[list[int]]) -> tuple[list[int], list[int]]:
    """Score only sequences that are not a token-id prefix of a longer one. Log-probs are causal."""
    order = sorted(range(len(seqs)), key=lambda i: len(seqs[i]), reverse=True)
    maximals: list[int] = []
    owner = [0] * len(seqs)
    for i in order:
        seq = seqs[i]
        found = None
        for m in maximals:
            base = seqs[m]
            if len(base) >= len(seq) and base[: len(seq)] == seq:
                found = m
                break
        if found is None:
            maximals.append(i)
            owner[i] = i
        else:
            owner[i] = found
    return maximals, owner


def _score_payload(input_ids: list[int]) -> dict:
    return {
        "input_ids": input_ids,
        "sampling_params": {
            "temperature": 0,
            "max_new_tokens": 0,
            "skip_special_tokens": False,
        },
        "return_logprob": True,
        "logprob_start_len": 0,
    }


def _logprobs_for_ids(result, expected_ids: list[int]) -> list:
    if isinstance(result, list):
        if len(result) != 1:
            raise ValueError(f"expected one teacher result, got {len(result)}")
        result = result[0]
    if not isinstance(result, dict):
        raise ValueError(f"teacher result has type {type(result).__name__}")
    if result.get("_opd_teacher_fallback"):
        raise RuntimeError(result.get("_opd_teacher_fallback_reason") or "teacher_failed")
    entries = (result.get("meta_info") or {}).get("input_token_logprobs")
    if not entries:
        raise ValueError("teacher response is missing meta_info.input_token_logprobs")
    got_ids = [int(entry[1]) for entry in entries]
    lps = [entry[0] for entry in entries]
    if got_ids == expected_ids:
        return lps
    # Some servers omit the leading placeholder and start at the first real log-prob.
    if got_ids == expected_ids[1:] and len(lps) == len(expected_ids) - 1:
        return [None, *lps]
    raise ValueError(f"teacher token ids mismatch: got {len(got_ids)} expected {len(expected_ids)}")


class _Turn:
    __slots__ = ("span", "full_ids", "completion_start", "student_pieces", "teacher_pieces")

    def __init__(self, span, full_ids, completion_start, student_pieces, teacher_pieces):
        self.span = span
        self.full_ids = full_ids
        self.completion_start = completion_start
        self.student_pieces = student_pieces
        self.teacher_pieces = teacher_pieces


def _plan_turns(args, sample: Sample) -> list[_Turn]:
    messages = _messages(args, sample)
    if not messages:
        return []
    loss_mask = sample.loss_mask
    if not loss_mask or len(loss_mask) != sample.response_length:
        logger.warning(
            "Cross-vocab OPD sample index=%s has no response loss_mask; no teacher signal",
            getattr(sample, "index", None),
        )
        return []
    if len(sample.tokens) < sample.response_length:
        raise ValueError(
            f"tokens length {len(sample.tokens)} < response_length {sample.response_length}"
        )

    teacher_tok = args._cross_vocab_teacher_tok
    student_tok = args._cross_vocab_student_tok
    tools = (sample.metadata or {}).get("tools")
    template_kwargs = _template_kwargs(args)
    prompt_len = len(sample.tokens) - sample.response_length
    # Pieces of the whole episode so a character split across the prompt/response boundary stays put.
    response_pieces = token_pieces(student_tok, sample.tokens)[prompt_len:]
    if len(response_pieces) != sample.response_length:
        raise ValueError("student piece length does not match the response")

    assistant_at = [
        i for i, message in enumerate(messages) if isinstance(message, dict) and message.get("role") == "assistant"
    ]
    spans = _mask_spans(loss_mask)
    n = min(len(assistant_at), len(spans))
    if len(assistant_at) != len(spans):
        logger.warning(
            "Cross-vocab OPD sample index=%s has %s assistant turns and %s generation spans; pairing %s",
            getattr(sample, "index", None),
            len(assistant_at),
            len(spans),
            n,
        )

    turns = []
    for k in range(n):
        ai = assistant_at[k]
        span = spans[k]
        try:
            history = messages[:ai]
            through = messages[: ai + 1]
            full = _render(teacher_tok, through, tools, False, template_kwargs)
            prompt = _render(teacher_tok, history, tools, True, template_kwargs)
            hist = _render(teacher_tok, history, tools, False, template_kwargs)
            full_ids = _encode(teacher_tok, full)
            full_pieces = token_pieces(teacher_tok, full_ids)
            piece_text = "".join(full_pieces)
            # Boundary is in the text the scored tokens actually spell.
            if prompt and piece_text.startswith(prompt):
                boundary = len(prompt)
            elif hist and piece_text.startswith(hist):
                boundary = len(hist)
            elif prompt and full.startswith(prompt):
                boundary = len(prompt)
                if piece_text != full:
                    boundary = len(piece_text)  # cannot place the cut; no completion tokens
            elif hist and full.startswith(hist):
                boundary = len(hist)
                if piece_text != full:
                    boundary = len(piece_text)
            else:
                logger.warning(
                    "Cross-vocab OPD sample index=%s turn %s: teacher render has no completion suffix; no signal",
                    getattr(sample, "index", None),
                    k,
                )
                continue
            start = _completion_start(full_pieces, boundary)
            turns.append(
                _Turn(
                    span=span,
                    full_ids=full_ids,
                    completion_start=start,
                    student_pieces=response_pieces[span[0] : span[1]],
                    teacher_pieces=full_pieces[start:],
                )
            )
        except Exception as exc:
            logger.warning(
                "Cross-vocab OPD sample index=%s turn %s render failed (%s: %s); no signal on that turn",
                getattr(sample, "index", None),
                k,
                type(exc).__name__,
                exc,
            )
    return turns


async def _score_and_align(args, sample: Sample) -> tuple[list[float], float, int]:
    _load_tokenizers(args)
    baseline = _rollout_log_probs(sample)
    turns = _plan_turns(args, sample)
    if not turns:
        return baseline, 0.0, 0

    maximals, owner = _prefix_owners([turn.full_ids for turn in turns])
    # Shortest maximal first so a teacher radix cache can reuse the shared prefix of later turns.
    score_order = sorted(maximals, key=lambda i: len(turns[i].full_ids))
    scored: dict[int, list] = {}
    failed = 0
    url = _teacher_url_for_sample(args, sample)
    for i in score_order:
        ids = turns[i].full_ids
        try:
            result = await _post_teacher_json(
                args, url, _score_payload(ids), sample, "Cross-vocab OPD teacher request"
            )
            scored[i] = _logprobs_for_ids(result, ids)
        except Exception as exc:
            failed += 1
            logger.warning(
                "Cross-vocab OPD sample index=%s turn score failed (%s: %s); no signal on that turn",
                getattr(sample, "index", None),
                type(exc).__name__,
                exc,
            )

    aligned = list(baseline)
    n_assigned = 0
    for i, turn in enumerate(turns):
        lps = scored.get(owner[i])
        if lps is None:
            continue
        if len(lps) < len(turn.full_ids):
            continue
        turn_lps = lps[: len(turn.full_ids)]
        comp_lps = turn_lps[turn.completion_start :]
        if len(comp_lps) != len(turn.teacher_pieces):
            continue
        a, b = turn.span
        span_aligned, n = align_logprobs(turn.student_pieces, turn.teacher_pieces, comp_lps, aligned[a:b])
        aligned[a:b] = span_aligned
        n_assigned += n

    overlap = n_assigned / sample.response_length if sample.response_length else 0.0
    return aligned, overlap, failed


async def reward_func_cross_vocab(args, sample: Sample, **kwargs):
    """Score every turn in the teacher's chat template and align those log-probs onto the student tokens."""
    try:
        aligned, overlap, failed = await _score_and_align(args, sample)
    except Exception as exc:
        logger.warning(
            "Cross-vocab OPD scoring failed for sample index=%s: %s: %s",
            getattr(sample, "index", None),
            type(exc).__name__,
            exc,
        )
        return {"_opd_teacher_fallback": True, "_opd_teacher_fallback_reason": type(exc).__name__}
    return {
        "aligned_log_probs": aligned,
        "cross_vocab_token_overlap": overlap,
        "opd_teacher_turn_fallbacks": failed,
    }


def post_process_cross_vocab(args, samples: list[Sample], teacher_results: list) -> None:
    """Write sample.teacher_log_probs. A failed score keeps rollout log-probs (no distillation signal)."""
    for sample, reward in zip(samples, teacher_results, strict=True):
        resp_len = sample.response_length
        if resp_len == 0:
            sample.teacher_log_probs = torch.empty(0, dtype=torch.float32)
            continue
        aligned = reward.get("aligned_log_probs") if isinstance(reward, dict) else None
        if not isinstance(reward, dict) or reward.get("_opd_teacher_fallback") or aligned is None:
            reason = "no_teacher"
            if isinstance(reward, dict):
                reason = reward.get("_opd_teacher_fallback_reason", reason)
            _use_student_log_probs_for_teacher(sample, reason)
            continue
        if len(aligned) != resp_len:
            _use_student_log_probs_for_teacher(sample, "length_mismatch")
            continue
        sample.teacher_log_probs = torch.tensor(aligned, dtype=torch.float32)
        if sample.metadata is None:
            sample.metadata = {}
        sample.metadata["cross_vocab_token_overlap"] = float(reward.get("cross_vocab_token_overlap") or 0.0)
        failed = int(reward.get("opd_teacher_turn_fallbacks") or 0)
        if failed:
            sample.metadata["opd_teacher_turn_fallbacks"] = failed

"""Reward for terminal OPD: the Harbor verdict drives GRPO, and the teacher's log-probs of the student's own tokens
give the per-token reverse-KL term Miles subtracts from the advantages (--use-opd, sampled-token form).

reward_func runs once per finished episode: it keeps the verdict the agent function left in the metadata and asks the
teacher server (--rm-url) to score the episode. post_process_rewards turns the teacher reply into
sample.teacher_log_probs and returns the group-normalised verdicts.

Every run names its teacher in a YAML (teacher_tokenizer_path plus chat-template kwargs). When that tokenizer is the
student's, the episode is scored as the student saw it (sample.tokens), the same call as a run with no teacher
tokenizer. A different tokenizer is rendered per turn in the teacher's chat template and aligned in
teacher_scoring.py.
"""

from typing import Any

import torch

from miles.ray.rollout.train_data_conversion import _normalize_rewards_by_rollout
from miles.rollout import on_policy_distillation as opd
from miles.utils.types import Sample

from . import teacher_scoring


def _same_tokenizer(args) -> bool:
    return teacher_scoring.teacher_uses_student_tokenizer(args)


async def reward_func(args, sample: Sample, **kwargs) -> dict[str, Any]:
    verdict = float((sample.metadata or {}).get("reward", 0.0) or 0.0)
    teacher = None
    if sample.response_length > 0:
        if _same_tokenizer(args):
            teacher = await opd.reward_func(args, sample)
        else:
            teacher = await teacher_scoring.reward_func_cross_vocab(args, sample)
    return {"verdict": verdict, "teacher": teacher}


def post_process_rewards(args, samples: list[Sample], **kwargs) -> tuple[list[float], list[float]]:
    raw = []
    rewards = [s.reward if isinstance(s.reward, dict) else {"verdict": float(s.reward or 0.0)} for s in samples]
    same = _same_tokenizer(args)
    if not same:
        teacher_scoring.post_process_cross_vocab(args, samples, [r.get("teacher") for r in rewards])
    for sample, r in zip(samples, rewards, strict=True):
        if same:
            teacher = r.get("teacher")
            if teacher is not None and sample.response_length > 0:
                sample.teacher_log_probs = opd._teacher_sampled_log_probs(teacher, sample.response_length)
            else:
                sample.teacher_log_probs = torch.zeros(sample.response_length, dtype=torch.float32)
        raw.append(float(r.get("verdict", 0.0)))
        sample.reward = raw[-1]  # the teacher reply is not needed past this point
